using System.Diagnostics;
using TextAnalysis;

// Build a ~1000-word corpus
var baseWords = new[]
{
    "the", "quick", "brown", "fox", "jumps", "over", "lazy", "dog",
    "performance", "benchmarking", "is", "important", "for", "understanding",
    "how", "code", "behaves", "under", "different", "runtime", "versions",
    "optimization", "matters", "when", "processing", "large", "amounts", "of", "text",
    "a", "comprehensive", "analysis"
};

var rng = new Random(42);
var parts = new string[1000];
for (int i = 0; i < parts.Length; i++)
    parts[i] = baseWords[rng.Next(baseWords.Length)];

var analyzer = new TextAnalyzer(string.Join(' ', parts));

const int warmupIterations = 500;
const int benchmarkIterations = 10_000;

Console.WriteLine($"Runtime: {System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription}");
Console.WriteLine($"Corpus: {analyzer.WordCount} words, {benchmarkIterations} iterations");
Console.WriteLine();

// Warm up
for (int i = 0; i < warmupIterations; i++)
{
    analyzer.AverageWordLength();
    analyzer.WordLengthHistogram();
    analyzer.UniqueWordCount();
}

// Benchmark each method
Benchmark("AverageWordLength", () => analyzer.AverageWordLength());
Benchmark("WordLengthHistogram", () => analyzer.WordLengthHistogram());
Benchmark("UniqueWordCount", () => analyzer.UniqueWordCount());

// GC stats
Console.WriteLine();
Console.WriteLine($"GC Gen0: {GC.CollectionCount(0)}, Gen1: {GC.CollectionCount(1)}, Gen2: {GC.CollectionCount(2)}");

static void Benchmark(string name, Func<object?> action)
{
    // Collect before measurement
    GC.Collect();
    GC.WaitForPendingFinalizers();
    GC.Collect();

    long allocBefore = GC.GetTotalAllocatedBytes(precise: true);
    var sw = Stopwatch.StartNew();
    for (int i = 0; i < benchmarkIterations; i++)
        action();
    sw.Stop();

    long allocAfter = GC.GetTotalAllocatedBytes(precise: true);
    double totalMs = sw.Elapsed.TotalMilliseconds;
    double perOpNs = totalMs * 1_000_000.0 / benchmarkIterations;
    long allocPerOp = (allocAfter - allocBefore) / benchmarkIterations;

    Console.WriteLine($"{name,-25} {perOpNs,10:F1} ns/op    {allocPerOp,8} B/op    (total: {totalMs,8:F2} ms)");
}

static void Benchmark(string name, Func<double> action)
{
    Benchmark(name, () => (object?)action());
}

static void Benchmark(string name, Func<int> action)
{
    Benchmark(name, () => (object?)action());
}

